scripts.script:
if (args.isCrit) {
    ChatMessage.create({
        content: `<div class="xjzl-chat-card">
            <div style="padding:5px 5px 5px 10px; background:rgba(255, 69, 0, 0.1); border-left:3px solid #ff4500; color:#d35400;">
                <strong>击退效果</strong><br>
                ${args.target.name} 被暴击击退 <b>1</b> 米。
            </div>
        </div>`,
        speaker: ChatMessage.getSpeaker({actor: actor})
    });
}

if (args.isBroken) {
    // 1. 发送击飞卡片
    ChatMessage.create({
        content: `<div class="xjzl-chat-card">
            <div style="padding:5px 5px 5px 10px; background:rgba(139, 0, 0, 0.1); border-left:3px solid #8b0000; color:#8b0000;">
                <strong>击破效果</strong><br>
                ${args.target.name} 被击飞 <b>1</b> 米并击倒！
            </div>
        </div>`,
        speaker: ChatMessage.getSpeaker({actor: actor})
    });
    // 2. 自动应用倒地
    await game.xjzl.api.effects.addEffect(args.target, "prone");
}

if (Macros.checkStance(actor, args)) {
    const effect = thisItem.effects.getName('沉舟');
    if (effect) {
        const data = effect.toObject();
        delete data._id;
        data.origin = thisItem.uuid;

        const stanceId = actor.system.martial.stance;
        const moveData = thisItem.system.moves.find(m => m.id === stanceId);
        const lvl = Math.max(1, moveData?.computedLevel || 1);
        const dmgBonus = 5 + (lvl - 1) * 5;
        foundry.utils.setProperty(data, "flags.xjzl-system.wuxue_chenzhouDmg", dmgBonus);

        await game.xjzl.api.effects.addEffect(actor, data);
        actor.showFloatyText("获得沉舟", {fill: "#00FFFF"});
    }
}

if (args.isHit) {
    // 1. 击退卡片
    ChatMessage.create({
        content: `<div class="xjzl-chat-card">
            <div style="padding:5px 5px 5px 10px; background:rgba(255, 165, 0, 0.1); border-left:3px solid #FFA500; color:#d35400;">
                <strong>击退效果</strong><br>
                ${args.target.name} 被击退 <b>3</b> 米。
            </div>
        </div>`,
        speaker: ChatMessage.getSpeaker({actor: actor})
    });

    // 2. 施加重创
    if (!args.target.system.martial?.stanceActive) {
        const effect = thisItem.effects.getName('重创');
        if (effect) {
            const data = effect.toObject();
            delete data._id;
            data.origin = thisItem.uuid;

            const lvl = Math.max(1, move.computedLevel || 1);
            const loss = 20 + (lvl - 1) * 10;
            foundry.utils.setProperty(data, "flags.xjzl-system.zhongchuangLoss", loss);

            await game.xjzl.api.effects.addEffect(args.target, data);
            ui.notifications.info(`${args.target.name} 受到重创。`);
        }
    }
}

if (args.move.type === 'basic' && args.move.id === 'opportunity') return;
const dmgBonus = thisEffect.getFlag("xjzl-system", "wuxue_chenzhouDmg") || 5;
args.output.damage += dmgBonus;
args.output.bonusDesc.push(`沉舟 +${dmgBonus}`);

if (!["waigong", "neigong", "fire", "poison", "mental"].includes(args.type)) return;
if ((args.hpLost + args.hutiLost) <= 0) return;
if (actor.isTakingZhongchuang) return;

const loss = thisEffect.getFlag("xjzl-system", "zhongchuangLoss") || 20;
actor.isTakingZhongchuang = true;
try {
    ChatMessage.create({
        content: `<div class="xjzl-chat-card">
            <div style="padding:5px 5px 5px 10px; background:rgba(139, 0, 0, 0.1); border-left:3px solid #8b0000; color:#8b0000;">
                <strong>重创发作</strong><br>
                ${actor.name} 伤口崩裂，额外流失 <b>${loss}</b> 点气血！
            </div>
        </div>`,
        speaker: ChatMessage.getSpeaker({actor: actor})
    });

    await actor.applyDamage({ amount: loss, type: 'liushi', isHit: true, ignoreMinDamage: true });
    await thisEffect.delete();
} finally {
    actor.isTakingZhongchuang = false;
}

const lvl = Math.max(1, move.computedLevel || 1);
const bonus = 1 + (lvl - 1);
// 技艺由于系统计算周期的原因无法在这里动态修改，已转为物品AE
S.skills.tancha.mod += bonus;
S.skills.dongcha.mod += bonus;
S.skills.zhuizong.mod += bonus;
S.skills.shuofu.mod += bonus;

// 阻断后续标准的卡片和目标判定流程
args.flags.abort = true;

const lvl = Math.max(1, move.computedLevel || 1);
// 难度随等级下降: 15 -> 10 -> 5
const dc = 15 - (lvl - 1) * 5;

// 投掷 D20
const r = await new Roll("1d20").evaluate();
if(game.dice3d) game.dice3d.showForRoll(r, game.user, true);

const isSuccess = r.total >= dc;
const resultHtml = isSuccess 
    ? "<span style='color:green; font-weight:bold;'><i class='fas fa-check'></i> 检定成功！主持人将协助你回忆。</span>" 
    : "<span style='color:red; font-weight:bold;'><i class='fas fa-times'></i> 检定失败...什么都想不起来。</span>";

// 发送自定义战报卡片
ChatMessage.create({
    speaker: ChatMessage.getSpeaker({actor: actor}),
    content: `<div class="xjzl-chat-card">
        <div style="border-left:4px solid #2c3e50; background:rgba(0,0,0,0.05); padding:6px; margin-left:2px;">
            <div style="font-weight:bold; color:#2c3e50;"><i class="fas fa-brain"></i> 回忆检定 (DC ${dc})</div>
            <div style="font-size:0.9em; margin-top:4px;">1d20 掷出 <b>${r.total}</b><br>${resultHtml}</div>
        </div>
    </div>`
});

if ((args.move.type === 'basic' && args.move.id !== 'opportunity')) return;
const mpCost = args.move.currentCost?.mp || 0;
if (mpCost <= 0) return;

const sourceItem = actor.items.find(i => i.name === '一以贯通' && i.type === 'wuxue');
if (!sourceItem) return;
const passiveMove = sourceItem.system.moves.find(m => m.name === '一以贯通');
const level = passiveMove?.computedLevel || 0;
if (level < 1) return;

const multiplier = Math.min(level, 3);
const bonus = Math.floor(mpCost * multiplier);

if (bonus > 0) {
    args.output.damage += bonus;
    args.output.bonusDesc.push(`一以贯通(Lv.${level}): +${bonus} (基于面板消耗${mpCost}预估，不代表最终结果)`);
}

if ((args.move.type === 'basic' && args.move.id !== 'opportunity')) return;
const mpCost = args.move.currentCost?.mp || 0;
const sourceItem = actor.items.find(i => i.name === '一以贯通' && i.type === 'wuxue');
if (!sourceItem) return;
const passiveMove = sourceItem.system.moves.find(m => m.name === '一以贯通');
const level = passiveMove?.computedLevel || 0;
if (level < 1) return;

const multiplier = Math.min(level, 3);

// 1. 先把 calc 阶段加的预估值扣掉
const previewBonus = Math.floor(mpCost * multiplier);
args.flags.damageResult.damage -= previewBonus;

// 2. 获取本次真正扣掉的内力 (含减耗、免费施法、濒死额外耗蓝)
const realMp = args.costConsumed?.mp || 0;
const realBonus = Math.floor(realMp * multiplier);

// 3. 把真正的加值加进去
args.flags.damageResult.damage += realBonus;

// 4. 更新卡片描述
if (realBonus !== previewBonus) {
    args.flags.damageResult.breakdown += `\n+ 一以贯通 (实扣${realMp}内力): +${realBonus}`;
}

// 5. 只要造成了额外伤害，发一张带边距的卡片
if (realBonus > 0) {
    const msg = `<div class="xjzl-chat-card" style="margin-left: 6px;"><div style="border-left: 3px solid #8e44ad; background: rgba(142,68,173,0.1); padding: 5px 8px;"><div style="font-weight:bold; color:#732d91;"><i class="fas fa-bolt"></i> 一以贯通 (Lv.${level})</div><div style="font-size:0.9em; color:#555; margin-top:3px;">实际消耗 ${realMp} 点内力，招式伤害提升 <span style="color:#8e44ad; font-weight:bold;">${realBonus}</span> 点！</div></div></div>`;
    ChatMessage.create({ speaker: ChatMessage.getSpeaker({actor: actor}), content: msg });
}
